class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context demonstrating EF Core 9 breaking change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=key", "MyDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 Cosmos provider now uses "$type" instead of
        // "Discriminator" for the discriminator property. Existing documents use "Discriminator",
        // so we must explicitly configure it to preserve backward compatibility.
        modelBuilder.Entity<Document>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Document>().ToContainer("Documents");
    }

    // BREAKING CHANGE 2: EF Core 9 Cosmos provider removed synchronous I/O support.
    // All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
    // See MigrationRunner.cs for the async query pattern.
}

class Document
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public string Content { get; set; } = default!;
}

