using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            using var transaction = db.Database.BeginTransaction();
            db.Database.Migrate();
            transaction.Commit();
        });
    }

    // BREAKING CHANGE 2 FIX: Cosmos provider no longer supports synchronous queries.
    // All Cosmos DB operations must be async in EF Core 9.
    async Task QueryCosmosAsync(CosmosDbContext cosmosDb)
    {
        // WRONG (throws InvalidOperationException in EF Core 9):
        //   var docs = cosmosDb.Documents.ToList();
        //   var doc = cosmosDb.Documents.First();

        // CORRECT: Use async equivalents
        var docs = await cosmosDb.Documents.ToListAsync();
        var doc = await cosmosDb.Documents.FirstOrDefaultAsync();
    }
}

